1	// Cold Email Engine — sending transport + message rendering (Phase 2).
2	//
3	// This module has TWO halves:
4	//
5	//   1. PURE rendering (`renderStepBody`, `buildMessage`, `injectTracking`,
6	//      markdown → HTML). No I/O, no DB, no network — the send worker AND the test
7	//      suite call these identically. Importing this module never opens a socket.
8	//
9	//   2. A pluggable `MailTransport` interface with a Nxeon Mail SMTP adapter
10	//      (reusing the platform's SMTP Setting mechanism from lib/mailer.ts) and an
11	//      SES adapter SEAM for later. Only `NxeonSmtpTransport.send()` touches the
12	//      network, and it is only ever reached from the send worker, which is hard-
13	//      gated behind the `cold_email_sending_enabled` kill-switch.
14	//
15	// SAFETY: nothing here checks the kill-switch or the suppression list itself —
16	// those gates live in the worker so they are enforced once, at the choke point,
17	// immediately before each send. This module assumes the caller has already
18	// cleared a message to send.
19	
20	import nodemailer from "nodemailer";
21	import { wrapEmail, appUrl } from "@/lib/email-render";
22	import {
23	  complianceFooter,
24	  unsubscribeToken,
25	  openTrackingToken,
26	  clickTrackingToken,
27	  normalizeDomain,
28	  type BrandLike,
29	} from "@/lib/coldemail/compliance";
30	
31	// ---------------------------------------------------------------------------
32	// Shapes
33	// ---------------------------------------------------------------------------
34	
35	export type SendIdentity = BrandLike & {
36	  id: string;
37	  name?: string | null;
38	  fromName?: string | null;
39	  fromEmail?: string | null;
40	  replyTo?: string | null;
41	  sendingDomain?: string | null;
42	};
43	
44	export type StepLike = { subject: string; bodyMarkdown: string };
45	
46	export type ContactLike = {
47	  id: string;
48	  email: string;
49	  fullName?: string | null;
50	  title?: string | null;
51	  business?: { name?: string | null } | null;
52	};
53	
54	export type RenderedMessage = {
55	  from: string;
56	  to: string;
57	  replyTo?: string;
58	  subject: string;
59	  html: string;
60	  text: string;
61	  headers: Record<string, string>;
62	};
63	
64	export type SendResult = { messageId?: string };
65	
66	/** A transport is anything that can put one fully-rendered message on the wire. */
67	export interface MailTransport {
68	  readonly name: string;
69	  send(msg: RenderedMessage): Promise<SendResult>;
70	}
71	
72	// ---------------------------------------------------------------------------
73	// Minimal, dependency-free markdown → HTML (no `marked` in this repo).
74	// Supports: paragraphs, line breaks, **bold**, *italic*, [text](url), and bare
75	// autolinks. Everything is escaped first, so raw HTML in the body is inert.
76	// ---------------------------------------------------------------------------
77	
78	function esc(s: string): string {
79	  return s
80	    .replace(/&/g, "&amp;")
81	    .replace(/</g, "&lt;")
82	    .replace(/>/g, "&gt;")
83	    .replace(/"/g, "&quot;");
84	}
85	
86	/** Render a markdown body to safe inline-styled HTML paragraphs. */
87	export function markdownToHtml(md: string): string {
88	  const inline = (raw: string): string => {
89	    let s = esc(raw);
90	    // [label](http…) links — label and URL are already escaped.
91	    s = s.replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, (_m, label, url) => {
92	      return `<a href="${url}" style="color:#6f47f5;text-decoration:underline;">${label}</a>`;
93	    });
94	    // Bare autolinks not already inside an <a href="…">.
95	    s = s.replace(/(^|[\s(])((https?:\/\/[^\s<)]+))/g, (_m, pre, url) => {
96	      return `${pre}<a href="${url}" style="color:#6f47f5;text-decoration:underline;">${url}</a>`;
97	    });
98	    s = s.replace(/\*\*([^*]+)\*\*/g, "<strong>$1</strong>");
99	    s = s.replace(/(^|[^*])\*([^*]+)\*/g, "$1<em>$2</em>");
100	    return s;
101	  };
102	
103	  const paragraphs = String(md ?? "")
104	    .replace(/\r\n?/g, "\n")
105	    .split(/\n{2,}/)
106	    .map((p) => p.trim())
107	    .filter(Boolean)
108	    .map((p) => {
109	      const body = p.split("\n").map(inline).join("<br/>");
110	      return `<p style="margin:0 0 16px;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;font-size:15px;line-height:1.65;color:#4a4763;">${body}</p>`;
111	    });
112	  return paragraphs.join("\n");
113	}
114	
115	// ---------------------------------------------------------------------------
116	// Variable substitution for personalization tokens ({{firstName}}, {{company}}…)
117	// ---------------------------------------------------------------------------
118	
119	export function contactVars(contact: ContactLike): Record<string, string> {
120	  const full = (contact.fullName ?? "").trim();
121	  const firstName = full.split(/\s+/)[0] ?? "";
122	  return {
123	    firstName,
124	    fullName: full,
125	    title: (contact.title ?? "").trim(),
126	    email: contact.email,
127	    company: (contact.business?.name ?? "").trim(),
128	  };
129	}
130	
131	function substitute(input: string, vars: Record<string, string>): string {
132	  return String(input ?? "").replace(/\{\{\s*([\w.]+)\s*\}\}/g, (_m, key: string) =>
133	    vars[key] !== undefined ? vars[key] : "",
134	  );
135	}
136	
137	// ---------------------------------------------------------------------------
138	// Tracking injection (open pixel + click-through rewriting). PURE.
139	// ---------------------------------------------------------------------------
140	
141	export function openPixelUrl(base: string, sendId: string): string {
142	  return `${base.replace(/\/$/, "")}/api/coldemail/track/open/${openTrackingToken(sendId)}`;
143	}
144	
145	export function clickWrapUrl(base: string, sendId: string, target: string): string {
146	  return `${base.replace(/\/$/, "")}/api/coldemail/track/click/${clickTrackingToken(sendId, target)}`;
147	}
148	
149	/**
150	 * Rewrite outbound `<a href="http…">` links through the click-tracking redirect
151	 * and append a 1x1 open pixel. Applied ONLY at send time — previews never call
152	 * this, so an operator's preview shows real, unwrapped links. The unsubscribe
153	 * link is deliberately left un-wrapped: it must remain a direct, one-click,
154	 * no-JS, no-redirect target per RFC 8058.
155	 */
156	export function injectTracking(html: string, sendId: string, base: string, opts: { skip?: (url: string) => boolean } = {}): string {
157	  const skip = opts.skip ?? (() => false);
158	  const rewritten = html.replace(/href="(https?:\/\/[^"]+)"/gi, (m, url: string) => {
159	    if (skip(url)) return m;
160	    return `href="${clickWrapUrl(base, sendId, url)}"`;
161	  });
162	  const pixel = `<img src="${openPixelUrl(base, sendId)}" width="1" height="1" alt="" style="display:none;width:1px;height:1px;border:0;" />`;
163	  return `${rewritten}\n${pixel}`;
164	}
165	
166	// ---------------------------------------------------------------------------
167	// Message rendering (PURE — the heart the tests exercise)
168	// ---------------------------------------------------------------------------
169	
170	/** Build the `From` header value from a brand identity. */
171	export function fromHeader(identity: SendIdentity): string {
172	  const email = (identity.fromEmail ?? "").trim();
173	  const name = (identity.fromName ?? identity.name ?? "").trim();
174	  return name ? `${name} <${email}>` : email;
175	}
176	
177	/** The From domain used for reputation-isolation checks. */
178	export function identityDomain(identity: SendIdentity): string {
179	  return normalizeDomain(identity.sendingDomain) || normalizeDomain(identity.fromEmail);
180	}
181	
182	export type BuildMessageOpts = {
183	  identity: SendIdentity;
184	  step: StepLike;
185	  contact: ContactLike;
186	  /** ColdSend id — anchors tracking tokens. Omit for a plain preview. */
187	  sendId?: string;
188	  /** Base URL for links (defaults to appUrl()). */
189	  base?: string;
190	  /** Extra disclosure line appended under the required footer. */
191	  footerDisclosure?: string;
192	  /** Inject open pixel + click tracking. FALSE for previews. */
193	  track?: boolean;
194	};
195	
196	/**
197	 * Render one SequenceStep into a fully-formed, compliant message:
198	 *  - subject + markdown body with {{tokens}} substituted,
199	 *  - the mandatory compliance footer (postal address + one-click unsubscribe),
200	 *  - `List-Unsubscribe` + `List-Unsubscribe-Post` headers (RFC 8058),
201	 *  - open/click tracking when `track` and a `sendId` are supplied.
202	 *
203	 * No network, no DB — deterministic given its inputs.
204	 */
205	export function buildMessage(opts: BuildMessageOpts): RenderedMessage {
206	  const { identity, step, contact } = opts;
207	  const base = (opts.base ?? appUrl()).replace(/\/$/, "");
208	  const vars = contactVars(contact);
209	
210	  const subject = substitute(step.subject, vars);
211	
212	  // Unsubscribe target (RFC 8058 one-click). Same HMAC token the endpoint verifies.
213	  const unsubToken = unsubscribeToken(contact.id, identity.id);
214	  const unsubscribeUrl = `${base}/api/coldemail/unsubscribe?token=${unsubToken}`;
215	
216	  // Body: markdown → HTML, then the mandatory footer as an HTML block.
217	  const bodyHtml = markdownToHtml(substitute(step.bodyMarkdown, vars));
218	  const footerText = complianceFooter(identity, unsubscribeUrl);
219	  const disclosure = (opts.footerDisclosure ?? "").trim();
220	  const footerHtml = renderFooterHtml(identity, unsubscribeUrl, disclosure);
221	
222	  let contentHtml = `${bodyHtml}\n${footerHtml}`;
223	  if (opts.track && opts.sendId) {
224	    contentHtml = injectTracking(contentHtml, opts.sendId, base, {
225	      // Never route the unsubscribe link through click-tracking.
226	      skip: (url) => url.includes("/api/coldemail/unsubscribe"),
227	    });
228	  }
229	
230	  const html = wrapEmail(contentHtml, { preheader: subject });
231	  const text = buildPlainText(substitute(step.bodyMarkdown, vars), footerText);
232	
233	  const headers: Record<string, string> = {
234	    // RFC 8058: HTTPS one-click unsubscribe. The POST target and the GET are the
235	    // same URL; the endpoint honours the POST immediately.
236	    "List-Unsubscribe": `<${unsubscribeUrl}>`,
237	    "List-Unsubscribe-Post": "List-Unsubscribe=One-Click",
238	    // Bulk-sender hygiene — a stable, honest precedence marker.
239	    "X-Nxeon-Cold-Email": "1",
240	  };
241	
242	  return {
243	    from: fromHeader(identity),
244	    to: contact.email,
245	    replyTo: (identity.replyTo ?? "").trim() || undefined,
246	    subject,
247	    html,
248	    text,
249	    headers,
250	  };
251	}
252	
253	/** The compliance footer, styled as an HTML block for the email body. */
254	function renderFooterHtml(identity: SendIdentity, unsubscribeUrl: string, disclosure: string): string {
255	  const address = (identity.physicalPostalAddress ?? "").trim() || "[physical postal address not set]";
256	  const parts = [
257	    disclosure ? esc(disclosure) : "You are receiving this message as a business contact.",
258	    `Our postal address: ${esc(address)}`,
259	    `To stop receiving these emails, <a href="${unsubscribeUrl}" style="color:#8a86a3;text-decoration:underline;">unsubscribe here</a>.`,
260	  ];
261	  return `<div style="margin-top:28px;padding-top:16px;border-top:1px solid #ecebf3;font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,Helvetica,Arial,sans-serif;font-size:12px;line-height:1.6;color:#8a86a3;">${parts.join("<br/>")}</div>`;
262	}
263	
264	/** Plain-text alternative: markdown stripped of decoration + the footer text. */
265	function buildPlainText(bodyMarkdown: string, footerText: string): string {
266	  const body = String(bodyMarkdown ?? "")
267	    .replace(/\r\n?/g, "\n")
268	    .replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g, "$1 ($2)")
269	    .replace(/\*\*([^*]+)\*\*/g, "$1")
270	    .replace(/\*([^*]+)\*/g, "$1")
271	    .trim();
272	  return `${body}\n\n---\n${footerText}\n`;
273	}
274	
275	// ---------------------------------------------------------------------------
276	// Transports
277	// ---------------------------------------------------------------------------
278	
279	type SmtpConfig = {
280	  host: string;
281	  port: number;
282	  user: string;
283	  pass: string;
284	  secure: boolean;
285	};
286	
287	/**
288	 * Load the platform SMTP settings the same way lib/mailer.ts does — the same
289	 * Setting rows (smtp_host/port/user/pass/secure), the same encrypted-password
290	 * tolerance, the same env fallback. Loaded lazily so importing this module never
291	 * touches the DB (keeps the module unit-testable and side-effect-free).
292	 */
293	async function loadSmtpConfig(): Promise<SmtpConfig> {
294	  const { db } = await import("@/lib/db");
295	  const { decryptSecret } = await import("@/lib/crypto-box");
296	  const rows = await db.setting.findMany({
297	    where: { key: { in: ["smtp_host", "smtp_port", "smtp_user", "smtp_pass", "smtp_secure"] } },
298	  });
299	  const s = Object.fromEntries(rows.map((r) => [r.key, r.value])) as Record<string, string>;
300	  const storedPass = s.smtp_pass;
301	  const pass = storedPass ? decryptSecret(storedPass) ?? storedPass : process.env.SMTP_PASS || "";
302	  return {
303	    host: s.smtp_host || process.env.SMTP_HOST || "",
304	    port: Number(s.smtp_port || process.env.SMTP_PORT || 587),
305	    user: s.smtp_user || process.env.SMTP_USER || "",
306	    pass,
307	    secure: (s.smtp_secure ?? process.env.SMTP_SECURE) === "true",
308	  };
309	}
310	
311	/**
312	 * Nxeon Mail (Mailcow) SMTP transport. The From identity is per-brand (passed on
313	 * each message) rather than the platform's transactional `smtp_from`, so a cold
314	 * campaign always sends as its dedicated sending identity — never as the platform.
315	 */
316	export class NxeonSmtpTransport implements MailTransport {
317	  readonly name = "nxeon-smtp";
318	  constructor(private readonly cfg: SmtpConfig) {}
319	
320	  private transporter() {
321	    if (!this.cfg.host) {
322	      return nodemailer.createTransport({ sendmail: true, newline: "unix", path: "/usr/sbin/sendmail" });
323	    }
324	    const servername = process.env.SMTP_TLS_SERVERNAME || undefined;
325	    return nodemailer.createTransport({
326	      host: this.cfg.host,
327	      port: this.cfg.port,
328	      secure: this.cfg.secure,
329	      auth: this.cfg.user ? { user: this.cfg.user, pass: this.cfg.pass } : undefined,
330	      ...(servername ? { tls: { servername } } : {}),
331	    });
332	  }
333	
334	  async send(msg: RenderedMessage): Promise<SendResult> {
335	    const info = await this.transporter().sendMail({
336	      from: msg.from,
337	      to: msg.to,
338	      replyTo: msg.replyTo,
339	      subject: msg.subject,
340	      html: msg.html,
341	      text: msg.text,
342	      headers: msg.headers,
343	    });
344	    return { messageId: (info as { messageId?: string })?.messageId };
345	  }
346	}
347	
348	/**
349	 * Amazon SES adapter SEAM. Left as a stub because SES is not provisioned yet and
350	 * this phase must not add dependencies or send anything. When a brand's domain
351	 * lives on SES, wire the AWS SDK here behind the same interface — the worker code
352	 * does not change.
353	 */
354	export class SesTransport implements MailTransport {
355	  readonly name = "ses";
356	  async send(_msg: RenderedMessage): Promise<SendResult> {
357	    throw new Error(
358	      "SES transport is not configured. The cold-email engine currently sends only via Nxeon Mail (SMTP). " +
359	        "Provision SES + wire the AWS SDK into SesTransport.send before selecting it.",
360	    );
361	  }
362	}
363	
364	export type TransportKind = "nxeon-smtp" | "ses";
365	
366	/**
367	 * Resolve the transport for a send. Defaults to Nxeon Mail SMTP. Async because
368	 * building the SMTP transport reads the Setting rows; kept off the module's import
369	 * path so tests can import the pure renderers without a DB.
370	 */
371	export async function getTransport(kind: TransportKind = "nxeon-smtp"): Promise<MailTransport> {
372	  if (kind === "ses") return new SesTransport();
373	  return new NxeonSmtpTransport(await loadSmtpConfig());
374	}
375

1	// Cold Email Engine — warmup engine (Phase 3).
2	//
3	// PURE + unit-testable: NO database access, NO I/O, NO network. The warmup
4	// worker step and the Warming UI both call these functions, and the test suite
5	// (test/coldemail-phase3.test.ts) exercises the ramp math directly.
6	//
7	// What "warming" means here (per the 2026 research): a brand-new inbox starts at
8	// a handful of sends/day and ramps to a safe ceiling over 2–4 weeks so the
9	// mailbox provider builds a history of trusted, low-and-slow sending before any
10	// real campaign volume. This module computes the ALLOWED volume for an inbox on
11	// a given day — it never sends anything.
12	//
13	// Honesty note baked into the design (research §2): we favour REAL-engagement
14	// warmup (genuine replies + spam-rescue on a vetted seed) over a synthetic
15	// auto-open pool, because Gmail/Yahoo increasingly detect and penalise synthetic
16	// warmup patterns. A synthetic warmup NETWORK that sends real mail between pooled
17	// mailboxes is deliberately OUT OF SCOPE (SaaS-pool territory) — see WARMUP_MODES.
18	
19	import { warmupDayIndex } from "@/lib/coldemail/compliance";
20	
21	export type WarmupStrategyKey = "CONSERVATIVE" | "STANDARD" | "AGGRESSIVE" | "ADAPTIVE";
22	export type WarmupModeKey = "POOL" | "REAL_SEED" | "HYBRID";
23	
24	/** A warmup ramp definition: from `startCap`/day up to `targetCap`/day over `rampDays`. */
25	export type WarmupPlan = {
26	  startCap: number;
27	  targetCap: number;
28	  rampDays: number;
29	};
30	
31	/**
32	 * Consensus 2026 ramp presets (research §2). New inbox ≈5–10/day → 30–50/day over
33	 * 2–4 weeks. AGGRESSIVE mirrors "pre-warmed inbox" guidance (start higher, ramp
34	 * faster) and should only be used on inboxes with prior sending history.
35	 */
36	export const WARMUP_PRESETS: Record<WarmupStrategyKey, WarmupPlan> = {
37	  CONSERVATIVE: { startCap: 5, targetCap: 30, rampDays: 28 },
38	  STANDARD: { startCap: 5, targetCap: 40, rampDays: 21 },
39	  AGGRESSIVE: { startCap: 10, targetCap: 50, rampDays: 14 },
40	  ADAPTIVE: { startCap: 5, targetCap: 40, rampDays: 21 },
41	};
42	
43	/**
44	 * Warmup modes and their honesty posture. The default is HYBRID/REAL_SEED; POOL
45	 * (synthetic auto-opens between simulated inboxes) carries an explicit warning
46	 * because it can be detected and hurt deliverability in 2026.
47	 */
48	export const WARMUP_MODES: Record<WarmupModeKey, { label: string; safe: boolean; note: string }> = {
49	  REAL_SEED: {
50	    label: "Real seed",
51	    safe: true,
52	    note: "Genuine replies + spam-rescue from a small vetted seed audience. Safest posture in 2026.",
53	  },
54	  HYBRID: {
55	    label: "Hybrid",
56	    safe: true,
57	    note: "Mostly real-engagement with limited pooled signals. Recommended default.",
58	  },
59	  POOL: {
60	    label: "Synthetic pool",
61	    safe: false,
62	    note: "Artificial opens/replies between simulated inboxes. Gmail/Yahoo increasingly detect this and it can DAMAGE deliverability. A real shared warmup network cannot be self-hosted (SaaS-pool territory) — out of scope.",
63	  },
64	};
65	
66	/** Clamp a plan into sane bounds so bad input can never produce an uncapped ramp. */
67	export function normalizePlan(plan: Partial<WarmupPlan> | null | undefined): WarmupPlan {
68	  const startCap = clampInt(plan?.startCap, 1, 200, 5);
69	  const targetCap = clampInt(plan?.targetCap, startCap, 500, Math.max(startCap, 40));
70	  const rampDays = clampInt(plan?.rampDays, 1, 90, 21);
71	  return { startCap, targetCap, rampDays };
72	}
73	
74	function clampInt(v: unknown, min: number, max: number, fallback: number): number {
75	  const n = Math.floor(Number(v));
76	  if (!Number.isFinite(n)) return fallback;
77	  return Math.min(max, Math.max(min, n));
78	}
79	
80	/**
81	 * The allowed daily volume for an inbox on warmup `dayIndex` (0-based: day 0 = the
82	 * first day → startCap). Linear ramp from startCap to targetCap across rampDays;
83	 * clamps to targetCap once the ramp completes. Deterministic and pure.
84	 */
85	export function warmupDailyLimit(dayIndex: number, plan: WarmupPlan): number {
86	  const p = normalizePlan(plan);
87	  const day = Number.isFinite(dayIndex) ? Math.max(0, Math.floor(dayIndex)) : 0;
88	  if (day <= 0) return p.startCap;
89	  if (day >= p.rampDays) return p.targetCap;
90	  const ramped = p.startCap + (p.targetCap - p.startCap) * (day / p.rampDays);
91	  return Math.min(p.targetCap, Math.max(p.startCap, Math.round(ramped)));
92	}
93	
94	/** Has the inbox finished its ramp (reached targetCap)? */
95	export function isWarmupComplete(dayIndex: number, plan: WarmupPlan): boolean {
96	  const p = normalizePlan(plan);
97	  return (Number.isFinite(dayIndex) ? Math.floor(dayIndex) : 0) >= p.rampDays;
98	}
99	
100	/**
101	 * ADAPTIVE back-off: when an inbox's health score dips, shrink today's allowance
102	 * rather than pushing full ramp volume through a struggling inbox (research §2/§4
103	 * "adaptive ramp down on soft-bounce spikes"). Healthy (≥80) → no change;
104	 * 60–79 → half; <60 → quarter. Never drops below 1.
105	 */
106	export function applyHealthBackoff(limit: number, healthScore: number): number {
107	  const h = Number.isFinite(healthScore) ? healthScore : 100;
108	  const base = Math.max(0, Math.floor(limit));
109	  if (h >= 80) return base;
110	  if (h >= 60) return Math.max(1, Math.round(base * 0.5));
111	  return Math.max(1, Math.round(base * 0.25));
112	}
113	
114	export type AllowedVolumeOpts = {
115	  warmupStartedAt?: Date | string | null;
116	  plan: WarmupPlan;
117	  /** Absolute per-inbox ceiling — the warmup ramp is additionally clamped by this. */
118	  dailyCap?: number;
119	  /** For ADAPTIVE: the inbox health score (0–100). */
120	  healthScore?: number;
121	  adaptive?: boolean;
122	  now?: Date | number;
123	};
124	
125	/**
126	 * Today's allowed send volume for an inbox: the warmup ramp value for the current
127	 * warmup day, clamped by the inbox's absolute dailyCap, with an optional adaptive
128	 * health back-off. `warmupStartedAt = null` means the inbox is on day 0 (never
129	 * uncapped). This is the single number the rotation engine budgets against.
130	 */
131	export function inboxAllowedVolume(opts: AllowedVolumeOpts): number {
132	  const plan = normalizePlan(opts.plan);
133	  const day = warmupDayIndex(opts.warmupStartedAt ?? null, opts.now ?? Date.now());
134	  let limit = warmupDailyLimit(day, plan);
135	  if (opts.adaptive) limit = applyHealthBackoff(limit, opts.healthScore ?? 100);
136	  const cap = opts.dailyCap && opts.dailyCap > 0 ? Math.floor(opts.dailyCap) : plan.targetCap;
137	  return Math.max(0, Math.min(limit, cap));
138	}
139	
140	/** The planned-ramp curve (day → planned volume) for charting the warmup. */
141	export function warmupRampCurve(plan: WarmupPlan): { day: number; planned: number }[] {
142	  const p = normalizePlan(plan);
143	  const out: { day: number; planned: number }[] = [];
144	  for (let d = 0; d <= p.rampDays; d++) out.push({ day: d, planned: warmupDailyLimit(d, p) });
145	  return out;
146	}
147	
148	export type WarmupStatus = {
149	  complete: boolean;
150	  day: number;
151	  rampDays: number;
152	  currentLimit: number;
153	  targetCap: number;
154	  label: string;
155	};
156	
157	/**
158	 * A plain-language warmup status for the UI: "Warming — day 9 of 21, ramping to
159	 * 40/day" or "Warmed — sending up to 40/day". `dayIndex` is 0-based; the label
160	 * shows 1-based days so a human reads "day 1" on the first day.
161	 */
162	export function warmupStatus(dayIndex: number, plan: WarmupPlan): WarmupStatus {
163	  const p = normalizePlan(plan);
164	  const day = Number.isFinite(dayIndex) ? Math.max(0, Math.floor(dayIndex)) : 0;
165	  const complete = day >= p.rampDays;
166	  const currentLimit = warmupDailyLimit(day, p);
167	  const label = complete
168	    ? `Warmed — sending up to ${p.targetCap}/day`
169	    : `Warming — day ${day + 1} of ${p.rampDays}, ramping to ${p.targetCap}/day (today ${currentLimit})`;
170	  return { complete, day, rampDays: p.rampDays, currentLimit, targetCap: p.targetCap, label };
171	}
