1	// Cold Email Engine — send-queue processor (Phase 2).
2	//
3	// Registered on the worker loop (worker/index.ts) and gated HARD behind the
4	// `cold_email_sending_enabled` master kill-switch: while that Setting is false
5	// this sweep returns immediately and NOTHING is scheduled, rendered, or sent.
6	//
7	// For each SENDING campaign it:
8	//   1. Re-checks brand send-eligibility (compliance + reputation isolation +
9	//      circuit-breaker pause). A blocked brand is skipped, never sent.
10	//   2. Expands the list → contacts → schedules a ColdSend per SequenceStep,
11	//      honouring delayDays (idempotent via the unique (campaign, contact, step)).
12	//   3. Sends due rows, enforcing at SEND TIME: suppression re-check, per-inbox
13	//      daily cap with the warmup ramp, and the send window — writing ColdSend
14	//      status (SENT/FAILED/SUPPRESSED) + an EmailEvent, throttled with jitter.
15	//
16	// Every count comes from the DB; the only external call is the SMTP send itself,
17	// which is unreachable in tests because the kill-switch keeps this inert.
18	
19	import { db } from "../lib/db";
20	import { getSetting, getSettingBool } from "../lib/settings";
21	import {
22	  isSuppressed,
23	  evaluateSendEligibility,
24	  protectedDomainSet,
25	  effectiveDailyCap,
26	  openTrackingToken,
27	  type SuppressionLike,
28	} from "../lib/coldemail/compliance";
29	import { buildMessage, getTransport, type SendIdentity, type MailTransport } from "../lib/coldemail/sender";
30	import { inboxAllowedVolume } from "../lib/coldemail/warmup";
31	import { selectNextInbox, type RotationInbox } from "../lib/coldemail/rotation";
32	import { logEvent } from "../lib/log";
33	
34	/**
35	 * A brand's rotation pool for this sweep: the ACTIVE inboxes on its authenticated
36	 * domains, each with the send identity + today's warmup-clamped allowance and the
37	 * live rotation candidate the selector mutates as sends go out.
38	 */
39	type PoolInbox = {
40	  candidate: RotationInbox;
41	  identity: SendIdentity;
42	  sendingDomainId: string;
43	};
44	
45	/**
46	 * Load a brand's rotation pool. Returns [] when the brand has no inboxes — the
47	 * worker then falls back to the Phase 2 brand-level cap path unchanged. Only
48	 * inboxes on a domain with SPF+DKIM+DMARC all verified are authenticated (authGreen).
49	 */
50	async function loadBrandRotationPool(brandId: string, brand: SendIdentity, now: Date): Promise<PoolInbox[]> {
51	  let inboxes;
52	  try {
53	    inboxes = await db.inbox.findMany({
54	      // Only ACTIVE inboxes on a domain that is not paused/burned. A domain-level
55	      // auto-pause therefore takes every one of its inboxes out of rotation.
56	      where: { status: "ACTIVE", sendingDomain: { brandId, status: { notIn: ["PAUSED", "BURNED"] } } },
57	      include: { sendingDomain: true },
58	    });
59	  } catch {
60	    return []; // tables not migrated on this env — behave like Phase 2
61	  }
62	  if (inboxes.length === 0) return [];
63	
64	  const dayStart = startOfUtcDay(now);
65	  const pool: PoolInbox[] = [];
66	  for (const ib of inboxes) {
67	    const d = ib.sendingDomain;
68	    const authGreen = !!(d?.spfVerified && d?.dkimVerified && d?.dmarcVerified);
69	    const allowedToday = inboxAllowedVolume({
70	      warmupStartedAt: ib.warmupStartedAt,
71	      plan: { startCap: ib.startCap, targetCap: ib.targetCap, rampDays: ib.rampDays },
72	      dailyCap: ib.dailyCap,
73	      healthScore: ib.healthScore,
74	      adaptive: ib.strategy === "ADAPTIVE",
75	      now,
76	    });
77	    const sentToday = await db.coldSend.count({ where: { inboxId: ib.id, sentAt: { gte: dayStart } } });
78	    pool.push({
79	      sendingDomainId: ib.sendingDomainId,
80	      candidate: {
81	        id: ib.id,
82	        status: ib.status as RotationInbox["status"],
83	        allowedToday,
84	        sentToday,
85	        authGreen,
86	        lastSendAt: ib.lastSendAt,
87	        minGapSeconds: ib.minGapSeconds,
88	      },
89	      // Send AS the inbox address, keeping the brand's name/postal/reply-to. This is
90	      // what makes rotation real — each message goes out from a different mailbox.
91	      identity: {
92	        ...brand,
93	        fromEmail: ib.email,
94	        sendingDomain: d ? `${d.subdomain ? d.subdomain + "." : ""}${d.domain}` : brand.sendingDomain,
95	      },
96	    });
97	  }
98	  return pool;
99	}
