124	/** Upper bound on sends per sweep — keeps each worker tick light + jitter sane. */
125	const MAX_SENDS_PER_SWEEP = 50;
126	/** Throttle window (ms) between real sends — jittered to look human, not blasty. */
127	const THROTTLE_MIN_MS = 800;
128	const THROTTLE_MAX_MS = 2600;
129	
130	const sleep = (ms: number) => new Promise((r) => setTimeout(r, ms));
131	const jitter = () => THROTTLE_MIN_MS + Math.floor(Math.random() * (THROTTLE_MAX_MS - THROTTLE_MIN_MS));
