366	/** Mark a campaign DONE once nothing is left QUEUED (all sends terminal). */
367	async function maybeCompleteCampaign(campaignId: string): Promise<void> {
368	  const remaining = await db.coldSend.count({ where: { campaignId, status: "QUEUED" } });
369	  if (remaining > 0) return;
370	  const any = await db.coldSend.count({ where: { campaignId } });
371	  if (any === 0) return; // nothing was ever scheduled — leave it SENDING
372	  await db.coldCampaign.update({ where: { id: campaignId }, data: { status: "DONE" } });
373	}
