65	      const sentVolume = await db.coldSend.count({ where: { inboxId: ib.id, sentAt: { gte: day0 } } });
66	      await db.warmupState.upsert({
67	        where: { inboxId_date: { inboxId: ib.id, date: day0 } },
68	        create: {
69	          inboxId: ib.id,
70	          date: day0,
71	          day,
72	          plannedVolume: currentRampCap,
73	          sentVolume,
74	          healthScore: ib.healthScore,
75	        },
76	        update: { day, plannedVolume: currentRampCap, sentVolume, healthScore: ib.healthScore },
77	      });
78	
79	      // Promote a warmed + authenticated inbox to ACTIVE (rotation-eligible). We only
80	      // auto-promote; we never auto-pause here (that's the rollup sweep's job).
81	      const d = ib.sendingDomain;
82	      const authGreen = !!(d?.spfVerified && d?.dkimVerified && d?.dmarcVerified);
83	      if (ib.status === "WARMING" && status.complete && authGreen) {
84	        await db.inbox.update({ where: { id: ib.id }, data: { status: "ACTIVE", pausedReason: "" } });
85	        await logEvent("info", "coldemail.warmup.complete", { inboxId: ib.id, day });
86	      }
87	    } catch (err) {
88	      await logEvent("error", "coldemail.warmup.sweep", { inboxId: ib.id, message: String(err) });
89	    }
