97	const EVENT_TO_COUNT: Record<string, Partial<MetricCounts>> = {
98	  SENT: { sent: 1 },
99	  DELIVERED: { delivered: 1 },
100	  HARD_BOUNCE: { hardBounce: 1 },
101	  SOFT_BOUNCE: { softBounce: 1 },
102	  OPEN: { opens: 1 },
103	  CLICK: { uniqueClicks: 1 },
104	  REPLY: { replies: 1 },
105	  POSITIVE_REPLY: { positiveReplies: 1, replies: 1 },
106	  COMPLAINT: { complaints: 1 },
107	  UNSUBSCRIBE: { unsubscribes: 1 },
108	};
109	
110	type Grouped = Map<string, MetricCounts>;
111	
112	function bump(map: Grouped, key: string | null | undefined, delta: Partial<MetricCounts>): void {
113	  if (!key) return;
114	  map.set(key, addCounts(map.get(key) ?? ZERO_COUNTS, delta));
115	}
116	
117	async function upsertMetrics(scope: "INBOX" | "DOMAIN" | "CAMPAIGN" | "BRAND", date: Date, map: Grouped): Promise<void> {
118	  for (const [scopeId, c] of map) {
119	    await db.metricsDaily
120	      .upsert({
121	        where: { scope_scopeId_date: { scope, scopeId, date } },
122	        create: { scope, scopeId, date, ...c },
123	        update: { ...c },
124	      })
125	      .catch(() => null);
126	  }
127	}
128	
129	/** Aggregate this UTC day's DeliverabilityEvent rows into MetricsDaily by scope. */
130	export async function coldEmailRollupSweep(): Promise<void> {
131	  const now = new Date();
132	  const day0 = startOfUtcDay(now);
133	
134	  let events;
135	  try {
136	    events = await db.deliverabilityEvent.findMany({
137	      where: { occurredAt: { gte: day0 } },
138	      select: { type: true, inboxId: true, sendingDomainId: true, campaignId: true },
139	    });
140	  } catch {
141	    return; // not migrated
142	  }
143	
144	  const byInbox: Grouped = new Map();
145	  const byDomain: Grouped = new Map();
146	  const byCampaign: Grouped = new Map();
147	  const brandByDomain = new Map<string, string>();
148	
149	  for (const e of events) {
150	    const delta = EVENT_TO_COUNT[e.type];
151	    if (!delta) continue;
152	    bump(byInbox, e.inboxId, delta);
153	    bump(byDomain, e.sendingDomainId, delta);
154	    bump(byCampaign, e.campaignId, delta);
155	  }
156	
157	  try {
158	    await upsertMetrics("INBOX", day0, byInbox);
159	    await upsertMetrics("DOMAIN", day0, byDomain);
160	    await upsertMetrics("CAMPAIGN", day0, byCampaign);
161	  } catch (err) {
162	    await logEvent("error", "coldemail.rollup.upsert", { message: String(err) });
163	  }
164	
165	  // Roll domains up to their brand for the agency/multi-client view.
166	  const byBrand: Grouped = new Map();
167	  for (const [domainId, c] of byDomain) {
168	    let brandId = brandByDomain.get(domainId);
169	    if (!brandId) {
170	      const d = await db.sendingDomain.findUnique({ where: { id: domainId }, select: { brandId: true } }).catch(() => null);
171	      brandId = d?.brandId;
172	      if (brandId) brandByDomain.set(domainId, brandId);
173	    }
174	    if (brandId) bump(byBrand, brandId, c);
175	  }
176	  await upsertMetrics("BRAND", day0, byBrand).catch(() => null);
177	
178	  // Auto-pause pass over the trailing window.
179	  const thresholds = await loadThresholds();
180	  await evaluateInboxes(thresholds);
181	  await evaluateDomains(thresholds);
182	}
183	
184	async function loadThresholds(): Promise<BurnThresholds> {
185	  const num = async (key: string) => {
186	    const v = Number(await getSetting(key));
187	    return Number.isFinite(v) && v > 0 ? v : undefined;
188	  };
189	  return resolveThresholds({
190	    bouncePauseInbox: await num("coldemail_bounce_pause_inbox"),
191	    bouncePauseDomain: await num("coldemail_bounce_pause_domain"),
192	    bounceHardStop: await num("coldemail_bounce_hard_stop"),
193	    complaintPauseDomain: await num("coldemail_complaint_pause_domain"),
194	  });
195	}
196	
197	/** RateStats for a scope over a trailing window (default 7 days). */
198	async function statsForScope(where: Record<string, unknown>, sinceDays = 7): Promise<RateStats> {
199	  const since = new Date(Date.now() - sinceDays * 86_400_000);
200	  const rows = await db.deliverabilityEvent
201	    .groupBy({ by: ["type"], where: { ...where, occurredAt: { gte: since } }, _count: { _all: true } })
202	    .catch(() => [] as { type: string; _count: { _all: number } }[]);
203	  let sent = 0,
204	    delivered = 0,
205	    bounces = 0,
206	    complaints = 0;
207	  for (const r of rows as { type: string; _count: { _all: number } }[]) {
208	    const n = r._count._all;
209	    if (r.type === "SENT") sent += n;
210	    else if (r.type === "DELIVERED") delivered += n;
211	    else if (r.type === "HARD_BOUNCE" || r.type === "SOFT_BOUNCE") bounces += n;
212	    else if (r.type === "COMPLAINT") complaints += n;
213	  }
214	  return { sent, delivered, bounces, complaints };
215	}
216	
217	async function writeHealthSnapshot(scope: "INBOX" | "DOMAIN", scopeId: string, stats: RateStats, rules: string[], paused: boolean): Promise<void> {
218	  const day0 = startOfUtcDay();
219	  const counts: MetricCounts = { ...ZERO_COUNTS, sent: stats.sent, delivered: stats.delivered, hardBounce: stats.bounces, complaints: stats.complaints };
220	  const score = healthScore(counts);
221	  const status = paused ? "PAUSED" : healthLevel(score) === "healthy" ? "HEALTHY" : healthLevel(score) === "warning" ? "WARNING" : "DANGER";
222	  await db.healthSnapshot
223	    .upsert({
224	      where: { scope_scopeId_date: { scope, scopeId, date: day0 } },
225	      create: { scope, scopeId, date: day0, healthScore: score, status, bounceRate: bounceRate(stats), complaintRate: complaintRate(stats), triggeredRules: rules.join(",") },
226	      update: { healthScore: score, status, bounceRate: bounceRate(stats), complaintRate: complaintRate(stats), triggeredRules: rules.join(",") },
227	    })
228	    .catch(() => null);
229	}
230	
231	async function evaluateInboxes(thresholds: BurnThresholds): Promise<void> {
232	  let inboxes;
233	  try {
234	    inboxes = await db.inbox.findMany({ where: { status: "ACTIVE" }, select: { id: true } });
235	  } catch {
236	    return;
237	  }
238	  for (const ib of inboxes) {
239	    const stats = await statsForScope({ inboxId: ib.id });
240	    const v = evaluateInboxAutoPause(stats, thresholds);
241	    await writeHealthSnapshot("INBOX", ib.id, stats, v.rules, v.pause);
242	    if (v.pause) {
243	      await db.inbox
244	        .update({ where: { id: ib.id }, data: { status: v.hardStop ? "BURNING" : "PAUSED", pausedReason: v.reasons.join("; ").slice(0, 400) } })
245	        .catch(() => null);
246	      await logEvent("warn", "coldemail.autopause.inbox", { inboxId: ib.id, rules: v.rules, bounceRate: bounceRate(stats) });
247	    }
248	  }
249	}
250	
251	async function evaluateDomains(thresholds: BurnThresholds): Promise<void> {
252	  let domains;
253	  try {
254	    domains = await db.sendingDomain.findMany({ where: { status: { in: ["ACTIVE", "WARMING"] } }, select: { id: true } });
255	  } catch {
256	    return;
257	  }
258	  for (const d of domains) {
259	    const stats = await statsForScope({ sendingDomainId: d.id });
260	    const v = evaluateDomainAutoPause(stats, thresholds);
261	    await writeHealthSnapshot("DOMAIN", d.id, stats, v.rules, v.pause);
262	    if (v.pause) {
263	      await db.sendingDomain
264	        .update({ where: { id: d.id }, data: { status: v.hardStop ? "BURNED" : "PAUSED", pausedReason: v.reasons.join("; ").slice(0, 400) } })
265	        .catch(() => null);
266	      // Take the domain's inboxes out of rotation too.
267	      await db.inbox.updateMany({ where: { sendingDomainId: d.id, status: "ACTIVE" }, data: { status: "PAUSED", pausedReason: "Domain auto-paused" } }).catch(() => null);
268	      await logEvent("warn", "coldemail.autopause.domain", { domainId: d.id, rules: v.rules, complaintRate: complaintRate(stats), bounceRate: bounceRate(stats) });
269	    }
270	  }
271	}
